import http from 'http';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Parse command line arguments
let model = 'default';
let inputs = ['N', 'N', 'N', 'N', 'N'];
let pretty = false;

const args = process.argv.slice(2);
for (let i = 0; i < args.length; i++) {
  if (args[i] === '--model' && args[i + 1]) {
    model = args[++i];
  } else if (args[i] === '--input') {
    for (let j = 0; j < 5 && i + 1 + j < args.length; j++) {
      if (args[i + 1 + j] && !args[i + 1 + j].startsWith('--')) {
        inputs[j] = args[i + 1 + j];
      }
    }
    i += 5;
  } else if (args[i] === '--pretty') {
    pretty = true;
  }
}

// Convert input format to Colormind API format
let locked = [];
for (const input of inputs) {
  if (input === 'N' || input === 'null') {
    locked.push(null);
  } else {
    const parts = input.split(',').map(Number);
    if (parts.length === 3) {
      locked.push(parts);
    }
  }
}

const postData = JSON.stringify({
  model: model,
  locked: locked
});

const options = {
  hostname: 'colormind.io',
  port: 80,
  path: '/api/',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => data += chunk);
  res.on('end', () => {
    const result = JSON.parse(data);
    console.log(JSON.stringify(result, null, 2));

    if (pretty && result.palette) {
      console.log('\n--- Palette Preview ---');
      const rgbToHex = (rgb) => {
        return '#' + rgb.map(x => x.toString(16).padStart(2, '0')).join('');
      };
      result.palette.forEach((color, i) => {
        console.log(`Color ${i + 1}: RGB(${color.join(', ')}) - ${rgbToHex(color)}`);
      });
    }
  });
});

req.on('error', (e) => console.error(e));
req.write(postData);
req.end();
EOF\n",
      "duration": 0.1
    },
    {
      "keystrokes": "chmod +x scripts/*.mjs\n",
      "duration": 0.1
    }
  ]
}

